}

// ============================================================================

// Exports
export PI, E, TAU, SQRT2, LN2, LN10
export abs, abs_float, sign, min, min_float, max, max_float, mod, gcd, lcm
export pow, pow_float, sqrt, cbrt
export exp, log, log10, log2
export sin, cos, tan, asin, acos, atan
export sinh, cosh, tanh
export floor, ceil, round, truncate
export dot, norm, distance, cross, trace
