function exists_impl(path: String) -> Bool = {
  false
}

function is_file_impl(path: String) -> Bool = {
  false
}

function is_directory_impl(path: String) -> Bool = {
  false
}

function delete_file_impl(path: String) -> Bool = {
  true
}

function copy_file_impl(source: String, dest: String) -> Bool = {
  true
}

function move_file_impl(source: String, dest: String) -> Bool = {
